	subtitle = "Предатель Каргата",
	found = "Крепость Черной горы",
	hint = [=[Найдите орка, который предал Орду и прячется в Крепости Черной горы.]=],
	allegiance = "Клан Черной горы",
	sections = {
		{
			title = "Обзор",
			text = [=[Грарк Лоркруб — {link:orcs}орк{/link} {link:horde}Орды{/link}, которого уличили в том, что он передавал клану Черной горы сведения о повседневных делах заставы Орды в {link:kargath}Каргат{/link}е. Он бежал через {link:searing-gorge}Тлеющее ущелье{/link}, сквозь гору и в {link:burning-steppes}Степи{/link} и теперь сидит в Крепости Черной горы под защитой клана. Он верит, что {link:blackrock-clan}клан Черной горы{/link} сделает его сильным.]=],
		},
		{
			title = "Значение",
			text = [=[Грарк показывает, как старая {link:horde}Орда{/link} все еще притягивает некоторых {link:orcs}орк{/link}ов, которых ведет {link:thrall}Тралл{/link}. Он видит силу в легионе Черной горы и не может понять, почему ее не видят другие.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он выдал клану Черной горы дела Орды в {link:kargath}Каргат{/link}е.]=],
		},
	},
	mentions = {
		{ text = "«Грарк Лоркруб»" },
		{ text = "«Шаткое положение»" },
	},
	bonds = {
		{ id = "thrall", name = "Тралл", note = "вождь, которого он предал" },
	},
})

Translate("ruRU", "gor-tesh", {
	title = "Гор'теш",
	subtitle = "Повелитель громил Огненного Чрева",
	found = [=[Укрепление клана Черной горы к западу от Скалы Молота Ужаса, близ Башни Пепла]=],
	hint = [=[Сразитесь с повелителем огров, который правит ограми Огненного Чрева из укрепления клана Черной горы к западу от Скалы Молота Ужаса.]=],
	allegiance = "Огры Огненного Чрева",
	sections = {
		{
			title = "Обзор",
			text = [=[Гор'теш — повелитель громил, глава {link:ogres}огр{/link}ов Огненного Чрева. Он не живет среди них на Скале Молота Ужаса. Он правит ими из укрепления клана Черной горы на западе, поближе к своим союзникам-{link:orcs}орк{/link}ам.]=],
		},
		{
			title = "Значение",
			text = [=[Гор'теш связывает {link:ogres}огр{/link}ов Огненного Чрева с кланом Черной горы. Его огры стерегут рудники клана и пути его снабжения.]=],
		},
	},
	mentions = {
		{ text = "«Гор'теш, повелитель громил»" },
		{ text = "«Голова {link:ogres}огр{/link}а на палке = праздник»" },
	},
	bonds = {
		{ id = "oralius", name = "Оралиус", note = "назначил его к смерти" },
	},
})

Translate("ruRU", "krom-grul", {
	title = "Кром'Грул",
	subtitle = "Огр Скалы Молота Ужаса",
	found = "Пещеры и рудники Скалы Молота Ужаса",
	hint = [=[Сразитесь с огром, который таится в пещерах Скалы Молота Ужаса.]=],
	allegiance = "Огры Огненного Чрева",
	sections = {
		{
			title = "Обзор",
			text = [=[Кром'Грул — {link:ogres}огр{/link} Скалы Молота Ужаса, который возглавил засаду на взвод Орды, посланный разузнать об обрядах огров Огненного Чрева. Он перебил всех, кроме одной — ее звали Ша'ни Гордый Клык, — и оставил ее для собственного обряда. Он приковал ее к алтарю и пытал, пока она не умерла. Потом он вырвал обручальное кольцо из ее лица и стал носить его на пальце.]=],
		},
		{
			title = "Значение",
			text = [=[Жестокость, которую явил Кром'Грул, показывает, чего требуют обряды {link:ogres}огр{/link}ов Огненного Чрева. Муж погибшей, {link:thal-trak-proudtusk}Тал'трак Гордый Клык{/link}, служит в {link:kargath}Каргат{/link}е в {link:badlands}Бесплодных землях{/link}. Это должно было стать ее последним заданием, и они собирались вместе устроить дом во Внутренних землях.]=],
		},
	},
	mentions = {
		{ text = "«{link:dreadmaul-rock}Скала Молота Ужаса{/link}»" },
		{ text = "«Кром'Грул»" },
	},
})
